import {boot,e,field,editAttrs} from '../creative-kit/ui.js?v=0.11.0';
import {make,validate,apply,markdown} from './state.js?v=0.11.0';
const labels={title:'Moment',actor:'Who is here?',trigger:'What just happened?',knows:'What do they know?',unknown:'What remains unknown?',can:'What can they do now?',stakes:'What is at stake?'};
function ideaCard(i){return `<article class="card intervention" data-drag-id="i:${e(i.id)}"><div class="card-top"><span>Intervention</span><button class="drag-handle" data-drag-handle data-action="move-menu" data-id="${e(i.id)}" aria-label="Move ${e(i.title)}">⠿</button></div><h3>${e(i.title)}</h3><p>${e(i.action||'Describe a change at this moment.')}</p>${i.stale?'<span class="tag amber">Scene changed · revisit fit</span>':''}<div class="card-actions"><button class="text-button" data-action="edit-idea" data-id="${e(i.id)}">Develop</button><button class="text-button" data-action="move-menu" data-id="${e(i.id)}">Move ↗</button></div></article>`;}
function render(w){const at=w.moments.findIndex(m=>m.id===w.selectedId);return `<div class="section-head"><div><h2>Walk through the moment.</h2><p>Keep what the actor knows separate from what you know now. Place an intervention where it could help.</p></div><div class="toolbar"><button data-action="walk" data-direction="-1" ${at===0?'disabled':''}>← Previous</button><span class="micro">${at+1} / ${w.moments.length}</span><button data-action="walk" data-direction="1" ${at===w.moments.length-1?'disabled':''}>Next →</button><button data-action="add-moment" ${w.moments.length>=8?'disabled':''}>+ Moment</button></div></div><div class="scene-track">${w.moments.map((m,index)=>`<section class="moment ${m.id===w.selectedId?'current':''}" data-drop-id="m:${e(m.id)}"><article class="moment-body" data-drag-id="m:${e(m.id)}"><div class="card-top"><button class="step-number" data-action="select" data-id="${e(m.id)}" aria-label="Walk to ${e(m.title)}">${index+1}</button><button class="drag-handle" data-drag-handle data-action="order-menu" data-id="${e(m.id)}" aria-label="Reorder ${e(m.title)}">⠿</button></div><h3>${e(m.title)}</h3><span class="actor">${e(m.actor||'Name an actor')}</span><p class="trigger">${e(m.trigger||'What happens?')}</p><div class="knowledge-pair"><div><span>KNOWS</span><p>${e(m.knows||'What is visible?')}</p></div><div><span>DOES NOT KNOW</span><p>${e(m.unknown||'What is uncertain?')}</p></div></div><div class="moment-detail"><span>CAN DO</span><p>${e(m.can||'Available actions')}</p><span>AT STAKE</span><p>${e(m.stakes||'Consequences')}</p></div><div class="card-actions"><button class="text-button" data-action="edit-moment" data-id="${e(m.id)}">Edit scene</button><button class="text-button" data-action="order-menu" data-id="${e(m.id)}">Reorder ↗</button></div></article><div class="intervention-stack"><span class="eyebrow">WHAT COULD HELP HERE?</span>${w.ideas.filter(i=>i.momentId===m.id).map(ideaCard).join('')||'<div class="empty">Drop an intervention here.</div>'}<button data-action="add-idea" data-moment="${e(m.id)}">+ Intervention</button></div></section>`).join('')}</div><section class="unplaced panel" data-drop-id="unplaced"><div class="section-head"><div><h2>Possibilities waiting for a moment</h2><p>Drag a handle into the scene, or use Move. Reordering a moment changes the sequence and prompts a fresh fit check.</p></div><button data-action="add-idea">+ Unplaced idea</button></div><div class="idea-bank">${w.ideas.filter(i=>i.momentId===null).map(ideaCard).join('')||'<p class="hint">All interventions are placed. Drop one here to detach it.</p>'}</div></section><aside class="scene-foot"><p>Vary the scene through <strong>My work → Duplicate this workspace</strong>. Change the actor, trigger or information, then revisit the interventions without losing the original.</p></aside>`;}
function editMoment(id,k){const m=k.w().moments.find(x=>x.id===id);k.open(Object.entries(labels).map(([f,label])=>field(`moment-${f}`,label,m[f],editAttrs('moments',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button class="delete" data-action="remove-moment" data-id="${e(id)}" ${k.w().moments.length===1?'disabled':''}>Remove moment</button></div><p class="hint">Removing a moment keeps its interventions in the unplaced bank.</p>`,'Edit this moment');}
function editIdea(id,k){const i=k.w().ideas.find(x=>x.id===id);k.open(field('idea-title','Intervention',i.title,editAttrs('ideas',id,'title'))+field('idea-action','What changes at this moment?',i.action,editAttrs('ideas',id,'action'))+field('idea-assumption','What must be true for it to help?',i.assumption,editAttrs('ideas',id,'assumption'))+field('idea-test','How would you try it in a replay or rehearsal?',i.test,editAttrs('ideas',id,'test'))+`<div class="toolbar"><button class="primary" data-action="review" data-id="${e(id)}">Fit checked for this scene</button><button data-action="close">Done</button><button class="delete" data-action="remove-idea" data-id="${e(id)}">Remove</button></div>`,'Develop the intervention');}
boot({route:'scenes',code:'S09',title:'Scene-first invention',description:'Make the situation concrete. Invent something that helps a particular person at a particular moment.',make,validate,apply,markdown,render,
 drop:(id,to,k)=>{const [type,item]=id.split(':');if(type==='i')k.act({type:'move-idea',id:item,momentId:to==='unplaced'?null:to.slice(2)});else if(to.startsWith('m:'))k.act({type:'reorder',id:item,before:to.slice(2)});},
 handle:(a,d,k)=>{if(a==='edit-moment')editMoment(d.id,k);else if(a==='edit-idea')editIdea(d.id,k);else if(a==='add-moment'){const id=k.uid();if(k.act({type:a,id}))editMoment(id,k);}else if(a==='add-idea'){const id=k.uid();if(k.act({type:a,id,momentId:d.moment}))editIdea(id,k);}else if(a==='walk'){const index=k.w().moments.findIndex(m=>m.id===k.w().selectedId)+Number(d.direction);if(k.w().moments[index])k.act({type:'select',id:k.w().moments[index].id},{checkpoint:false});}else if(a==='select')k.act({type:a,id:d.id},{checkpoint:false});else if(a==='move-menu')k.open('<div class="dialog-options">'+k.w().moments.map(m=>`<button data-action="place" data-id="${e(d.id)}" data-moment="${e(m.id)}">${e(m.title)}</button>`).join('')+`<button data-action="place" data-id="${e(d.id)}">Keep unplaced</button></div>`,'Where could this help?');else if(a==='place'){k.close();k.act({type:'move-idea',id:d.id,momentId:d.moment||null});}else if(a==='order-menu')k.open('<p>Move this moment to another position in the sequence.</p><div class="dialog-options">'+k.w().moments.map((m,index)=>`<button data-action="reorder" data-id="${e(d.id)}" data-before="${e(m.id)}" ${m.id===d.id?'disabled':''}>Position ${index+1}: ${e(m.title)}</button>`).join('')+'</div>','Reorder scene');else if(['reorder','remove-moment','remove-idea','review'].includes(a)){k.close();k.act({type:a,id:d.id,before:d.before});}}
});
